#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define W for (i=0;i<tmp;i++)

int i;
int radix = 255;
int fraction = 0;
long range = 1;
int tmp;
int cc[1000000];

int OFF1 = 5;
int OFF2 = 2;
int INTSIZE = 4;
int LITSIZE = 4;

int pc(unsigned char c) {
  putchar(c);
  return (int)c;
}

void put_bit(int bit, int ctx) {
  int *counts = cc + ctx * 2;
  int split = range * -~*counts / (*counts + counts[1] + 2);

  if (bit) {
    fraction += split;
    range -= split;
  } else {
    range = split;
  }

  counts[bit]++;

  while (range < radix) {
    pc((fraction / (range / radix)) + 1);
    fraction %= (range / radix);
    fraction *= radix;
    range *= radix;
  }
}

void put_integer(int val, int bits, int ctx) {
  int subtract_it = 1 << bits;
  val += subtract_it;

  int high_bit = bits;
  while ((1 << high_bit) > val) high_bit--;

  for (int b = high_bit; b >= bits; b--) {
    put_bit(0, ++bits + ctx * 99);
  }
  put_bit(1, ++bits + ctx * 99);

  for (int b = bits - 1; b >= 0; b--) {
    put_bit((val >> b) & 1, ctx);
  }
}

int main() {
  char data[10000];
  int len = 0;

  while (fread(data + len, 1, 1, stdin) == 1 && len < 9999) {
    len++;
  }

  // Encode number of operations
  put_integer(len, 9, 0);

  // For now, just encode as literals
  for (int i = 0; i < len; i++) {
    put_bit(0, 1);  // literal flag
    put_integer(data[i], LITSIZE, 9);
  }

  // Flush remaining bits
  pc((fraction / (range / radix)) + 1);

  return 0;
}
