    fraction *= radix;
  }

  int *counts = cc + ctx * 2;
  int split = range * (-~*counts) / (*counts + counts[1] + 2);

  if (bit) {
    fraction += split;
    range -= split;
  } else {
    range = split;
  }

  counts[bit]++;

  while (range < radix) {
    put_byte((unsigned char)((fraction / (range > 0 ? range / radix : 1)) + 1));
    fraction %= (range > 0 ? range / radix : 1);
    fraction *= radix;
    range *= radix;
  }
