int main() {
  char data[10000];
  int len = 0;
  int c;

  while ((c = getchar()) != EOF && len < 9999) {
    data[len++] = (char)c;
  }

  /* First, encode the count */
  int subtract_it = 1 << 9;
  int count_val = len + subtract_it;

  /* Encode count in variable-length format */
  int nbits = 9;
  int count_bits = nbits;
  while (count_bits < 32 && !((1 << count_bits) >= count_val)) {
    count_bits++;
  }

  /* Send stop code for variable-length: emit 1 bits until we reach the value */
  for (int b = nbits; b < count_bits; b++) {
    put_bit(0, b + 0 * 99);
  }
  put_bit(1, count_bits + 0 * 99);

  /* Now send the actual bits of count_val */
  for (int b = count_bits - 1; b >= nbits; b--) {
    put_bit((count_val >> b) & 1, 0);
  }

  /* Simple encoding: just literals for now */
  for (int i = 0; i < len; i++) {
    put_bit(0, 1);  /* literal, not match */

    unsigned char ch = (unsigned char)data[i];
    /* Sign bit: positive */
    put_bit(0, 8);

    /* Encode the character value */
    int char_val = ch + (1 << LITSIZE);
    int char_bits = LITSIZE;

    for (int b = char_bits; b < 32 && !((1 << b) >= char_val); b++) {
      char_bits = b + 1;
    }

    for (int b = char_bits; b > LITSIZE; b--) {
      put_bit(0, b - 1 + 9 * 99);
    }
    put_bit(1, char_bits + 9 * 99);

    for (int b = char_bits - 1; b >= LITSIZE; b--) {
      put_bit((char_val >> b) & 1, 9);
    }
  }

  return 0;
}
