#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int radix = 255;
int fraction = 0;
long range = 1;
int cc[1000000];

void put_bit(int bit, int ctx) {
  /* Emit bits until range is large enough */
  while (range < radix) {
    /* Output one byte: fraction/(range/radix) rounded, then +1 */
    if (range > 0) {
      unsigned char b = (unsigned char)((fraction / (range / radix)) + 1);
      putchar(b);
      fraction %= (range / radix);
      fraction *= radix;
      range *= radix;
    } else {
      range = radix;
      fraction = 0;
    }
  }

  int *counts = cc + ctx * 2;
  int split = range * (-~*counts) / (*counts + counts[1] + 2);

  if (bit) {
    fraction += split;
    range -= split;
  } else {
    range = split;
  }

  counts[bit]++;
}

void put_integer(int val, int nbits, int ctx) {
  int subtract_it = 1 << nbits;
  int result = val + subtract_it;

  ctx *= 99;

  /* Emit the "stop code": 0 bits for each position, then 1 */
  int b = nbits;
  while ((1 << b) <= result) {
    put_bit(0, ++b + ctx);
  }
  put_bit(1, b + ctx);
  b--;

  /* Emit the actual bits */
  for (int j = 0; j < b; j++) {
    put_bit((result >> (b - 1 - j)) & 1, ctx);
  }
}

int main() {
  char buf[10000];
  int len = 0;
  int c;

  while ((c = getchar()) != EOF && len < 9999) {
    buf[len++] = (char)c;
  }

  /* Emit count */
  put_integer(len, 9, 0);

  /* Emit each byte as a literal */
  for (int i = 0; i < len; i++) {
    unsigned char ch = (unsigned char)buf[i];

    /* Literal flag (bit 0 = literal) */
    put_bit(0, 1);

    /* Sign bit */
    int val = (int)(signed char)ch;
    put_bit((val < 0) ? 1 : 0, 8);

    /* Encode value */
    int abs_val = (val < 0) ? -val : val;
    put_integer(abs_val, 4, 9);
  }

  /* Flush remaining output */
  while (range < radix) {
    unsigned char b = (unsigned char)((fraction / (range / radix)) + 1);
    putchar(b);
    fraction %= (range / radix);
    fraction *= radix;
    range *= radix;
  }

  return 0;
}
