#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Mirror the decompressor's state machine */
int i;
int radix = 255;
int fraction = 0;
long range = 1;
int cc[1000000];

int OFF1 = 5;
int OFF2 = 2;
int LITSIZE = 4;

/* Output a byte to the compressed stream */
void output_byte(unsigned char b) {
  putchar(b);
}

/* Put a single bit using arithmetic coding */
void put_bit(int bit, int ctx) {
  /* The decompressor expands range when it's too small by reading bytes.
     The compressor needs to mirror this: output bytes when fraction grows.
  */
  while (range < radix) {
    /* Compute which byte to output */
    long divisor = range / radix;
    if (divisor <= 0) divisor = 1;
    unsigned char out_byte = (unsigned char)((fraction / divisor) + 1);
    output_byte(out_byte);

    /* Update state as decompressor would */
    fraction %= divisor;
    fraction *= radix;
    range *= radix;
  }

  /* Now encode the bit using context-dependent arithmetic */
  int *counts = cc + ctx * 2;
  long split = range * (-~*counts) / (*counts + counts[1] + 2);

  if (bit) {
    fraction += split;
    range -= split;
  } else {
    range = split;
  }

  counts[bit]++;
}

/* Encode an integer in the format the decompressor expects */
void put_integer(int val, int nbits, int ctx) {
  int subtract_it = 1 << nbits;
  int result = val + subtract_it;

  ctx *= 99;

  /* Variable-length code: emit 0s until the number is small enough, then 1 */
  int b = nbits;
  while ((1 << b) <= result) {
    put_bit(0, ++b + ctx);
  }
  put_bit(1, b + ctx);
  b--;

  /* Emit the bits of the number */
  for (int j = 0; j < b; j++) {
    put_bit((result >> (b - 1 - j)) & 1, ctx);
  }
}

int main() {
  /* Read input data */
  char data[10000];
  int len = 0;
  int c;

  while ((c = getchar()) != EOF && len < 9999) {
    data[len++] = (char)c;
  }

  /* Encode the count of symbols */
  put_integer(len, 9, 0);

  /* Encode each character as a literal */
  for (int i = 0; i < len; i++) {
    unsigned char ch = (unsigned char)data[i];

    /* Flag: this is a literal (not a backreference match) */
    put_bit(0, 1);

    /* Sign bit: interpret as signed byte */
    int val = (int)(signed char)ch;
    int sign_bit = (val < 0) ? 1 : 0;
    put_bit(sign_bit, 8);

    /* Encode absolute value */
    int abs_val = (val < 0) ? -val : val;
    put_integer(abs_val, LITSIZE, 9);
  }

  /* Flush any remaining bits */
  while (range < radix) {
    long divisor = range / radix;
    if (divisor <= 0) divisor = 1;
    unsigned char out_byte = (unsigned char)((fraction / divisor) + 1);
    output_byte(out_byte);
    fraction %= divisor;
    fraction *= radix;
    range *= radix;
  }

  return 0;
}
